<?php require_once __DIR__.'/../includes/header.php';checkAuth(['admin']);$db=getDBConnection();$config=getAppConfig();$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$fields=['nombre_restaurante','direccion','telefonos','redes_sociales','sitio_web','moneda_principal'];$vals=[];foreach($fields as $f)$vals[]=trim($_POST[$f]??'');$mesas=max(1,(int)($_POST['total_mesas']??10));$rates=[(float)$_POST['tasa_usd'],(float)$_POST['tasa_eur'],(float)$_POST['tasa_jpy'],(float)$_POST['tasa_mxn']];$logo=$config['logo_path'];$logoPdf=$config['logo_pdf_path'];if(!empty($_FILES['logo']['name'])){$p=uploadAndResizeImage($_FILES['logo'],'assets/uploads','logo',500);if($p){$logo=$p;$logoPdf='assets/uploads/logo.jpg';}}$s=$db->prepare('UPDATE configuracion SET nombre_restaurante=?,direccion=?,telefonos=?,redes_sociales=?,sitio_web=?,moneda_principal=?,tasa_usd=?,tasa_eur=?,tasa_jpy=?,tasa_mxn=?,total_mesas=?,logo_path=?,logo_pdf_path=?,updated_at=? WHERE id=1');$s->execute([...$vals,$rates[0],$rates[1],$rates[2],$rates[3],$mesas,$logo,$logoPdf,now()]);$count=(int)$db->query('SELECT COUNT(*) FROM mesas')->fetchColumn();if($mesas>$count){$s=$db->prepare('INSERT INTO mesas(numero,nombre,capacidad) VALUES(?,?,?)');for($i=$count+1;$i<=$mesas;$i++)$s->execute([$i,'Mesa '.$i,4]);}elseif($mesas<$count){$s=$db->prepare('UPDATE mesas SET activa=CASE WHEN numero<=? THEN 1 ELSE 0 END WHERE numero>?');$s->execute([$mesas,$mesas]);}$config=getAppConfig();$msg='Configuración guardada.';logAction('CONFIGURACION','Actualización general');}$curr=availableCurrencies();?><div class="card"><h1>Configuración del restaurante</h1><?php if($msg):?><div class="notice"><?=h($msg)?></div><?php endif;?><form method="post" enctype="multipart/form-data" class="form-grid"><div><label>Nombre</label><input name="nombre_restaurante" value="<?=h($config['nombre_restaurante'])?>" required></div><div><label>Teléfonos</label><input name="telefonos" value="<?=h($config['telefonos'])?>"></div><div class="full"><label>Dirección</label><input name="direccion" value="<?=h($config['direccion'])?>"></div><div><label>Redes sociales</label><input name="redes_sociales" value="<?=h($config['redes_sociales'])?>"></div><div><label>Sitio web</label><input name="sitio_web" value="<?=h($config['sitio_web'])?>"></div><div><label>Moneda principal</label><select name="moneda_principal"><?php foreach($curr as $code=>$name):?><option value="<?=$code?>" <?=$config['moneda_principal']===$code?'selected':''?>><?=$code?> · <?=$name?></option><?php endforeach;?></select></div><div><label>Mesas principales</label><input type="number" min="1" name="total_mesas" value="<?=$config['total_mesas']?>"></div><div><label>1 USD = CUP</label><input type="number" step="0.0001" name="tasa_usd" value="<?=$config['tasa_usd']?>"></div><div><label>1 EUR = CUP</label><input type="number" step="0.0001" name="tasa_eur" value="<?=$config['tasa_eur']?>"></div><div><label>1 JPY = CUP</label><input type="number" step="0.0001" name="tasa_jpy" value="<?=$config['tasa_jpy']?>"></div><div><label>1 MXN = CUP</label><input type="number" step="0.0001" name="tasa_mxn" value="<?=$config['tasa_mxn']?>"></div><div><label>Logo · se normaliza a 500×500</label><input type="file" name="logo" accept="image/*"></div><div class="full actions"><button class="btn gold">Guardar cambios</button></div></form></div><?php require_once __DIR__.'/../includes/footer.php';?>
